#[test]
fn sweep() {
    let mut x: u64 = 0x9E3779B97F4A7C15;
    let mut next = || { x ^= x << 13; x ^= x >> 7; x ^= x << 17; x };
    let edges: Vec<u64> = { let mut v = vec![]; for k in 0..20000u64 { v.push(u64::MAX - k); v.push(k); } for k in [1615u64,1616,1617,9998,9999,10000,10001] { v.push(k); v.push(u64::MAX-k);} v };
    let mut bad = 0u64;
    for i in 0..2_000_000u64 {
        let a = if i % 3 == 0 { edges[(next() % edges.len() as u64) as usize] } else { next() >> (next() % 64) };
        let f = if i % 2 == 0 { edges[(next() % edges.len() as u64) as usize] } else { next() >> (next() % 64) };
        let r = reference(u64::MAX, a, f);
        let bal = match r { Some(t) => [t, t.wrapping_sub(1), next()][(i % 3) as usize], None => next() };
        let got = authorize(bal, a, f).map(|z| z.total_debit);
        if got != reference(bal, a, f) { bad += 1; if bad < 3 { println!("MISMATCH b={} a={} f={} got={:?} ref={:?}", bal, a, f, got, reference(bal,a,f)); } }
    }
    for a in [0u64, 1, 5000, 10000] { for k in 0..30000u64 { let f = (u64::MAX - k).wrapping_sub(a); let r = reference(u64::MAX,a,f); if let Some(t)=r { for bal in [t, t-1] { if authorize(bal,a,f).map(|z|z.total_debit) != reference(bal,a,f) { bad+=1; } } } } }
    println!("bad={}", bad);
    assert_eq!(bad, 0);
}
